import { DomainError } from "./DomainError";

export class Product {
  private availableUnits: number;
  private reservedUnits = 0;

  constructor(
    readonly id: string,
    readonly name: string,
    initialStock: number,
  ) {
    if (!Number.isInteger(initialStock) || initialStock < 0) {
      throw new DomainError("invalid", `Initial stock for ${id} must be a non-negative integer`);
    }
    this.availableUnits = initialStock;
  }

  get available(): number {
    return this.availableUnits;
  }

  get reserved(): number {
    return this.reservedUnits;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.availableUnits;
  }

  reserve(quantity: number): void {
    if (!this.canReserve(quantity)) {
      throw new DomainError(
        "conflict",
        `Insufficient stock for ${this.id}: requested ${quantity}, available ${this.availableUnits}`,
      );
    }
    this.availableUnits -= quantity;
    this.reservedUnits += quantity;
  }

  release(quantity: number): void {
    const released = Math.min(quantity, this.reservedUnits);
    this.reservedUnits -= released;
    this.availableUnits += released;
  }

  /** Reserved units leave the warehouse (order shipped). */
  dispatch(quantity: number): void {
    this.reservedUnits -= Math.min(quantity, this.reservedUnits);
  }
}

